import type { Difficulty, DomainId, Question, QuestionCollection } from "./questions";

const q = (
  id: string,
  collection: QuestionCollection,
  domain: DomainId,
  topic: string,
  difficulty: Difficulty,
  prompt: string,
  options: string[],
  correct: number | number[],
  explanation: string,
): Question => {
  const originalCorrect = Array.isArray(correct) ? correct : [correct];
  const shift = [...id].reduce((sum, character) => sum + character.charCodeAt(0), 0) % options.length;
  return {
    id,
    collection,
    domain,
    topic,
    difficulty,
    prompt,
    options: options.map((_, index) => options[(index + shift) % options.length]),
    correct: originalCorrect.map((index) => (index - shift + options.length) % options.length),
    explanation,
  };
};

